      debris.rotation.y += dt * 0.012;
      if (exit.open) {
        exit.doorOpen = Math.min(1, exit.doorOpen + dt * 0.9);
        exit.door.position.y = 1.7 + exit.doorOpen * 3.35;
      }
    },
  };
  return level;
}

