  for (const ry of [0, Math.PI / 2, Math.PI, Math.PI * 1.5]) {
    addStrip(root, mats, Math.sin(ry) * 2.32, 6.6, 1.5 + Math.cos(ry) * 2.32, 0.08, 4.6, 0.08, 'cyan', ry);
  }

  // Rotating gyro rings.
  const gyroA = new THREE.Mesh(new THREE.TorusGeometry(4.3, 0.045, 6, 64), mats.cyanSoft);
  gyroA.rotation.x = Math.PI / 2;
  gyroA.position.set(0, 8.0, 1.5);
  root.add(gyroA);
  const gyroB = new THREE.Mesh(new THREE.TorusGeometry(3.4, 0.022, 5, 64), mats.orangeSoft);
  gyroB.rotation.x = Math.PI / 2;
  gyroB.position.set(0, 8.0, 1.5);
  root.add(gyroB);

  const anchor = addAnchor(root, mats, { x: 0, y: 1.8, z: 3.78, ry: 0, name: 'ANCHOR 02' });

  // Three satellite islands.
  const islands = [
    { x: -16.4, z: -4, w: 11.2, d: 11, top: 1.4, panel: { x: -21.74, y: 3.0, z: -4, ry: Math.PI / 2 } },
    { x: 16.4, z: -4, w: 11.2, d: 11, top: 1.4, panel: { x: 21.74, y: 3.0, z: -4, ry: -Math.PI / 2 } },
    { x: 0, z: -16.2, w: 12.4, d: 10.2, top: 2.4, panel: { x: 0, y: 4.0, z: -23.72, ry: 0 } },
  ];
  for (const [i, is] of islands.entries()) {
    addBox(root, boxes, mats, { x: is.x, y: is.top - 0.62, z: is.z, w: is.w, h: 1.24, d: is.d, mat: 'floor' });
    addBox(root, boxes, mats, { x: is.x, y: is.top - 1.9, z: is.z, w: is.w - 1.1, h: 1.4, d: is.d - 1.1, mat: 'metalDark', collide: false });
    const stripMat = i === 2 ? 'orange' : 'cyan';
    addStrip(root, mats, is.x, is.top + 0.02, is.z - is.d / 2 + 0.22, is.w - 0.8, 0.04, 0.12, stripMat);
    addStrip(root, mats, is.x, is.top + 0.02, is.z + is.d / 2 - 0.22, is.w - 0.8, 0.04, 0.12, stripMat);
    addPortalPanel(root, panels, mats, { ...is.panel, w: 5.4, h: 4.8 });
    addHazardGlow(root, mats, is.x, is.z, -11.8, is.w - 2, is.d - 2);
  }

  // Cores on the three islands.
  const cores = [
    addCore(root, mats, { x: -16.4, y: 3.0, z: -4 }, textures.glowTexture),
    addCore(root, mats, { x: 16.4, y: 3.0, z: -4 }, textures.glowTexture),
    addCore(root, mats, { x: 0, y: 4.0, z: -16.2 }, textures.glowTexture),
  ];

  const exit = addDoor(root, mats, { x: -2.27, y: 0, z: 1.65, ry: -Math.PI / 2, label: 'EXTRACTION GATE' });

  const mainSign = makeSignTexture({
    eyebrow: 'TEST CHAMBER 02 // TRIANGULATION',
    title: 'THREE SIGNALS',
    sub: 'ONE LINK  /  THREE RECOVERIES',
    color: '#72e9ff',
  });
  addSign(root, mainSign, 0, 7.3, 10.8, 8.8, 3.3, 0, 0.94);
  addStrip(root, mats, -4.8, 5.5, 10.8, 0.04, 3.1, 0.04, 'cyan');
  addStrip(root, mats, 4.8, 5.5, 10.8, 0.04, 3.1, 0.04, 'cyan');

  // Light shafts and linking filaments.
  for (const is of islands) {
    addLightCone(root, is.x, is.top + 6.5, is.z, 3.1, 11.0, is.z < -10 ? 0xff7a3b : 0x5ce8ff, 0.03);
    const from = new THREE.Vector3(0, 8.6, 1.5);
    const to = new THREE.Vector3(is.x, is.top + 2.2, is.z);
    const dir = new THREE.Vector3().subVectors(to, from);
    const filament = new THREE.Mesh(
      new THREE.CylinderGeometry(0.012, 0.012, dir.length(), 5),
      is.z < -10 ? mats.orangeSoft : mats.cyanSoft,
    );
    filament.position.copy(from).addScaledVector(dir, 0.5);
    filament.quaternion.setFromUnitVectors(UP, dir.clone().normalize());
    root.add(filament);
  }

  addDebrisRing(root, mats, 11.2, 0.4, 34);
  const light = new THREE.PointLight(0x61e9ff, 5.5, 22, 2);
  light.position.set(0, 7.4, 3.2);
  root.add(light);
  const warm = new THREE.PointLight(0xff6b2e, 4.0, 16, 2);
  warm.position.set(0, 3.0, -16.2);
  root.add(warm);

  const level = {
    index: 1,
    name: 'TRIANGULATION',
    tag: 'TEST CHAMBER 02',
    brand: 'HORIZON INITIATIVE',
    brief: 'Recover the three flux cores. The tower gate opens when the array is complete.',
    hint: 'Stand on the hub. Aim at any island panel, then step into the cyan anchor to cross. Walk back through your portal to return.',
    spawn: { x: 0, y: 0.02, z: 10.0, yaw: 0, pitch: -0.02 },
    boxes, panels, cores, anchor, exit, root,
    required: 3,
    bounds,
    extras: { gyroA, gyroB },
    animate(t, dt) {
      anchor.discMaterial.uniforms.uTime.value = t;
      anchor.arcs[0].rotation.z += dt * 0.32;
      anchor.arcs[1].rotation.z -= dt * 0.2;
      gyroA.rotation.z += dt * 0.08;
      gyroB.rotation.z -= dt * 0.13;
      for (const core of cores) {
        if (core.collected) continue;
        core.group.position.y = core.baseY + Math.sin(t * 1.8 + core.position.x * 0.3) * 0.1;
        core.inner.rotation.y += dt * core.spin;
        core.inner.rotation.x += dt * 0.3;
        core.shell.rotation.y -= dt * 0.42;
        core.ringA.rotation.z += dt * 0.42;
        core.ringB.rotation.y += dt * 0.3;
      }
      if (exit.open) {
        exit.doorOpen = Math.min(1, exit.doorOpen + dt * 0.9);
        exit.door.position.y = 1.7 + exit.doorOpen * 3.35;
      }
    },
  };
  return level;
}

function buildChamberThree(ctx) {
  const { mats, textures } = ctx;
  const root = new THREE.Group();
  const boxes = [];
  const panels = [];
  const bounds = { minX: -23, maxX: 23, minZ: -23, maxZ: 23, height: 28.2 };

  addRoomShell(root, boxes, mats, bounds, { zRibs: 5.2 });

  // Spawn deck.
  addBox(root, boxes, mats, { x: 0, y: -0.55, z: 17.2, w: 14, h: 1.1, d: 10.2, mat: 'floor' });
  addStrip(root, mats, 0, 0.02, 12.18, 13.6, 0.04, 0.12, 'orange');

  // Central reactor spine.
  addBox(root, boxes, mats, { x: 0, y: 8.2, z: 2.0, w: 5.2, h: 16.4, d: 5.2, mat: 'wallDark' });
  addBox(root, boxes, mats, { x: 0, y: 16.7, z: 2.0, w: 6.2, h: 0.5, d: 6.2, mat: 'metalDark', collide: false });
  for (let i = 0; i < 5; i++) {
    addStrip(root, mats, 0, 1.2 + i * 3.0, 4.62, 4.1, 0.06, 0.06, i === 2 ? 'orange' : 'cyan');
  }
  const gyro = new THREE.Mesh(new THREE.TorusGeometry(5.4, 0.05, 6, 80), mats.cyanSoft);
  gyro.rotation.x = Math.PI / 2;
  gyro.position.set(0, 11.2, 2.0);
  root.add(gyro);
  const gyro2 = new THREE.Mesh(new THREE.TorusGeometry(4.2, 0.028, 5, 80), mats.orangeSoft);
  gyro2.rotation.x = Math.PI / 2;
  gyro2.position.set(0, 11.2, 2.0);
  root.add(gyro2);

  const anchor = addAnchor(root, mats, { x: 0, y: 1.8, z: 4.62, ry: 0, name: 'ANCHOR 03' });

  // Four vertical challenge platforms.
  const platforms = [
    { x: -17.2, z: 4.0, w: 10.2, d: 10.0, top: 5.7, panel: { x: -22.72, y: 7.3, z: 4.0, ry: Math.PI / 2 }, core: { x: -16.0, y: 7.3, z: 4.0 } },
    { x: 17.2, z: 4.0, w: 10.2, d: 10.0, top: 10.7, panel: { x: 22.72, y: 12.3, z: 4.0, ry: -Math.PI / 2 }, core: { x: 16.0, y: 12.3, z: 4.0 } },
    { x: 0, z: -16.5, w: 12.0, d: 9.0, top: 15.3, panel: { x: 0, y: 16.9, z: -22.72, ry: 0 }, core: { x: 0, y: 16.9, z: -16.5 } },
    { x: -16.8, z: 13.0, w: 10.4, d: 9.5, top: 19.7, panel: { x: -22.72, y: 21.3, z: 13.0, ry: Math.PI / 2 }, core: { x: -15.8, y: 21.3, z: 13.0 } },
  ];

  for (const [i, p] of platforms.entries()) {
    addBox(root, boxes, mats, { x: p.x, y: p.top - 0.55, z: p.z, w: p.w, h: 1.1, d: p.d, mat: 'floor' });
    addBox(root, boxes, mats, { x: p.x, y: p.top - 1.8, z: p.z, w: p.w - 1.2, h: 1.5, d: p.d - 1.2, mat: 'metalDark', collide: false });
    addStrip(root, mats, p.x, p.top + 0.02, p.z + p.d / 2 - 0.2, p.w - 1.2, 0.04, 0.11, i % 2 ? 'orange' : 'cyan');
    addStrip(root, mats, p.x, p.top + 0.02, p.z - p.d / 2 + 0.2, p.w - 1.2, 0.04, 0.11, i % 2 ? 'orange' : 'cyan');
    addPortalPanel(root, panels, mats, { ...p.panel, w: 5.4, h: 5.0 });
    addHazardGlow(root, mats, p.x, p.z, -11.9, p.w - 2, p.d - 2);
  }

  const cores = platforms.map((p) => addCore(root, mats, p.core, textures.glowTexture));

  // Extraction loft and its final portal surface.
  addBox(root, boxes, mats, { x: 0, y: 21.5, z: -17.7, w: 10.6, h: 1.1, d: 9.2, mat: 'floor' });
  addBox(root, boxes, mats, { x: 0, y: 20.2, z: -17.7, w: 9.0, h: 1.5, d: 7.6, mat: 'metalDark', collide: false });
  addStrip(root, mats, 0, 22.02, -13.2, 9.4, 0.04, 0.12, 'cyan');
  const finalPanel = addPortalPanel(root, panels, mats, { x: 0, y: 23.6, z: -22.72, w: 5.8, h: 5.2, ry: 0, enabled: false });
  const exit = addExtraction(root, mats, { x: 0, y: 22.0, z: -17.0, ry: 0 });

  // Extra portal surface on the spawn deck, for freedom.
  addPortalPanel(root, panels, mats, { x: -6.8, y: 2.3, z: 12.1, w: 3.6, h: 4.4, ry: 0 });

  const mainSign = makeSignTexture({
    eyebrow: 'TEST CHAMBER 03 // SINGULARITY',
    title: 'THE LONG WAY UP',
    sub: 'FOUR CORES  /  ONE EMITTER  /  NO FALLBACK',
    color: '#ff8a45',
  });
  addSign(root, mainSign, 0, 9.4, 17.6, 9.4, 3.5, 0, 0.94);
  addStrip(root, mats, -5.2, 7.4, 17.6, 0.04, 3.3, 0.04, 'orange');
  addStrip(root, mats, 5.2, 7.4, 17.6, 0.04, 3.3, 0.04, 'orange');

  // High catwalk silhouettes.
  for (const [x, z, w, d] of [[-20.5, -9, 4.6, 12], [20.5, -9, 4.6, 12], [0, -21.4, 15, 2.4]]) {
    addBox(root, boxes, mats, { x, y: 24.5, z, w, h: 0.5, d, mat: 'metalDark', collide: false });
    for (let i = -2; i <= 2; i++) {
      addBox(root, boxes, mats, { x: x + i * 1.2, y: 24.0, z, w: 0.06, h: 0.72, d: d - 0.2, mat: 'cyan', collide: false });
    }
  }

  for (const p of platforms) {
    addLightCone(root, p.x, p.top + 5.0, p.z, 3.0, 11, p.core.y > 15 ? 0xff6e30 : 0x5ce8ff, 0.028);
    const from = new THREE.Vector3(0, 14.5, 2.0);
    const to = new THREE.Vector3(p.x, p.top + 2.2, p.z);
    const dir = new THREE.Vector3().subVectors(to, from);
    const filament = new THREE.Mesh(new THREE.CylinderGeometry(0.012, 0.012, dir.length(), 5), p.core.y > 15 ? mats.orangeSoft : mats.cyanSoft);
    filament.position.copy(from).addScaledVector(dir, 0.5);
    filament.quaternion.setFromUnitVectors(UP, dir.clone().normalize());
    root.add(filament);
  }

  addDebrisRing(root, mats, 14.0, 1.2, 44);
  const beacon = new THREE.PointLight(0x68eaff, 7.0, 28, 2);
  beacon.position.set(0, 12, 3.0);
  root.add(beacon);
  const warm = new THREE.PointLight(0xff6b30, 6.0, 22, 2);
  warm.position.set(0, 23.0, -16.0);
  root.add(warm);

  const level = {
    index: 2,
    name: 'SINGULARITY',
    tag: 'TEST CHAMBER 03',
    brand: 'HORIZON INITIATIVE',
    brief: 'Recover all four flux cores. Then reach the extraction loft before containment resets the chamber.',
    hint: 'The final panel stays dark until the array is complete. After the fourth core, look up and place your portal on the loft panel.',
    spawn: { x: 0, y: 0.02, z: 18.0, yaw: 0, pitch: 0.08 },
    boxes, panels, cores, anchor, exit, root,
    required: 4,
    bounds,
    finalPanel,
    extras: { gyro, gyro2 },
    animate(t, dt) {
      anchor.discMaterial.uniforms.uTime.value = t;
      anchor.arcs[0].rotation.z += dt * 0.32;
      anchor.arcs[1].rotation.z -= dt * 0.2;
      gyro.rotation.z += dt * 0.055;
      gyro2.rotation.z -= dt * 0.09;
      for (const core of cores) {
        if (core.collected) continue;
        core.group.position.y = core.baseY + Math.sin(t * 1.7 + core.position.x * 0.21) * 0.12;
        core.inner.rotation.y += dt * core.spin;
        core.inner.rotation.x += dt * 0.32;
        core.shell.rotation.y -= dt * 0.4;
        core.ringA.rotation.z += dt * 0.4;
        core.ringB.rotation.y += dt * 0.28;
      }
      if (exit.open) {
        exit.ring.material = mats.cyan;
        exit.ring2.material = mats.cyan;
        exit.beam.material.color.setHex(0x4beaff);
        exit.beam.material.opacity = 0.14 + Math.sin(t * 2.2) * 0.035;
      }
    },
  };
  return level;
}

export function buildLevel(index, ctx) {
  if (index === 0) return buildChamberOne(ctx);
  if (index === 1) return buildChamberTwo(ctx);
  return buildChamberThree(ctx);
}

export function setPanelEnabled(panel, mats, enabled) {
  panel.enabled = enabled;
  for (const pip of panel.pips) pip.material = enabled ? mats.cyan : mats.red;
}

// Re-export a small helper used by main for the reticle glow.
export { makeGlowTexture };

export class AudioManager {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.muted = false;
    this.ambientStarted = false;
    this.stepTimer = 0;
  }

  init() {
    if (this.ctx) {
      if (this.ctx.state === 'suspended') this.ctx.resume();
      return;
    }
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return;
    this.ctx = new AC();
    this.master = this.ctx.createGain();
    this.master.gain.value = this.muted ? 0 : 0.42;
    this.master.connect(this.ctx.destination);
    this.startAmbience();
  }

  startAmbience() {
    if (!this.ctx || this.ambientStarted) return;
    this.ambientStarted = true;
    const ctx = this.ctx;

    const bedGain = ctx.createGain();
    bedGain.gain.value = 0.055;
    bedGain.connect(this.master);

    for (const [freq, detune, gain] of [[41, 0, 0.52], [61.5, 4, 0.28], [82.5, -3, 0.16]]) {
      const osc = ctx.createOscillator();
      const g = ctx.createGain();
      osc.type = 'sine';
      osc.frequency.value = freq;
      osc.detune.value = detune;
      g.gain.value = gain;
      osc.connect(g).connect(bedGain);
      osc.start();

      const lfo = ctx.createOscillator();
      const lfoGain = ctx.createGain();
      lfo.frequency.value = 0.035 + Math.random() * 0.04;
      lfoGain.gain.value = gain * 0.55;
      lfo.connect(lfoGain).connect(g.gain);
      lfo.start();
    }

    // Distant air-handler noise.
    const len = ctx.sampleRate * 3;
    const buffer = ctx.createBuffer(1, len, ctx.sampleRate);
    const data = buffer.getChannelData(0);
    let last = 0;
    for (let i = 0; i < len; i++) {
      const white = Math.random() * 2 - 1;
      last = last * 0.985 + white * 0.015;
      data[i] = last * 1.8;
    }
    const src = ctx.createBufferSource();
    src.buffer = buffer;
    src.loop = true;
    const filter = ctx.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.value = 190;
    const g = ctx.createGain();
    g.gain.value = 0.16;
    src.connect(filter).connect(g).connect(this.master);
    src.start();
  }

  setMuted(muted) {
    this.muted = muted;
    if (this.master) this.master.gain.setTargetAtTime(muted ? 0 : 0.42, this.ctx.currentTime, 0.03);
  }

  toggleMute() {
    this.setMuted(!this.muted);
    return this.muted;
  }

  now() {
    return this.ctx ? this.ctx.currentTime : 0;
  }

  tone(freq, duration = 0.2, type = 'sine', gain = 0.08, slideTo = null, delay = 0) {
    if (!this.ctx || this.muted) return;
    const t0 = this.now() + delay;
    const osc = this.ctx.createOscillator();
    const g = this.ctx.createGain();
    osc.type = type;
    osc.frequency.setValueAtTime(freq, t0);
    if (slideTo) osc.frequency.exponentialRampToValueAtTime(slideTo, t0 + duration);
    g.gain.setValueAtTime(0.0001, t0);
    g.gain.exponentialRampToValueAtTime(gain, t0 + 0.012);
    g.gain.exponentialRampToValueAtTime(0.0001, t0 + duration);
    osc.connect(g).connect(this.master);
    osc.start(t0);
    osc.stop(t0 + duration + 0.03);
  }

  noise(duration = 0.2, gain = 0.08, type = 'bandpass', freq = 900, q = 0.8, delay = 0) {
    if (!this.ctx || this.muted) return;
    const t0 = this.now() + delay;
    const len = Math.max(1, Math.floor(this.ctx.sampleRate * duration));
    const buffer = this.ctx.createBuffer(1, len, this.ctx.sampleRate);
    const data = buffer.getChannelData(0);
    for (let i = 0; i < len; i++) data[i] = (Math.random() * 2 - 1) * (1 - i / len);
    const src = this.ctx.createBufferSource();
    src.buffer = buffer;
    const filter = this.ctx.createBiquadFilter();
    filter.type = type;
    filter.frequency.setValueAtTime(freq, t0);
    filter.frequency.exponentialRampToValueAtTime(Math.max(80, freq * 0.35), t0 + duration);
    filter.Q.value = q;
    const g = this.ctx.createGain();
    g.gain.value = gain;
    src.connect(filter).connect(g).connect(this.master);
    src.start(t0);
  }

  click() {
    this.tone(700, 0.055, 'square', 0.025, 430);
  }

  portal() {
    this.noise(0.34, 0.12, 'bandpass', 1600, 1.4);
    this.tone(180, 0.28, 'sawtooth', 0.055, 680);
    this.tone(920, 0.18, 'sine', 0.04, 1320, 0.05);
  }

  placeDenied() {
    this.tone(130, 0.12, 'square', 0.035, 90);
  }

  recall() {
    this.noise(0.2, 0.06, 'highpass', 1500, 0.8);
    this.tone(700, 0.2, 'sine', 0.04, 220);
  }

  teleport() {
    this.noise(0.5, 0.14, 'bandpass', 2200, 1.2);
    this.tone(120, 0.42, 'sine', 0.07, 780);
    this.tone(560, 0.24, 'triangle', 0.04, 1100, 0.04);
    this.tone(280, 0.3, 'sine', 0.035, 160, 0.1);
  }

  pickup() {
    const notes = [523.25, 659.25, 783.99, 1046.5];
    notes.forEach((f, i) => this.tone(f, 0.35, 'sine', 0.055 - i * 0.006, f * 1.01, i * 0.055));
    this.noise(0.22, 0.04, 'highpass', 3200, 0.6);
  }

  unlock() {
    const chord = [196, 246.94, 293.66, 392, 493.88];
    chord.forEach((f, i) => this.tone(f, 0.85, 'triangle', 0.03, f * 1.005, i * 0.035));
    this.tone(98, 0.9, 'sine', 0.045, 72);
    this.noise(0.7, 0.05, 'lowpass', 900, 0.5);
  }

  fail() {
    this.tone(110, 0.5, 'sawtooth', 0.06, 58);
    this.noise(0.4, 0.08, 'lowpass', 500, 0.6);
  }

  success() {
    [261.63, 329.63, 392, 523.25, 659.25, 783.99].forEach((f, i) => {
      this.tone(f, 1.1, 'sine', 0.035, f, i * 0.09);
    });
    this.noise(1.2, 0.035, 'highpass', 2400, 0.4);
  }

  step(amount = 1) {
    if (!this.ctx || this.muted) return;
    const now = this.now();
    if (now - this.stepTimer < 0.34) return;
    this.stepTimer = now;
    this.noise(0.07, 0.018 * amount, 'lowpass', 420, 1.2);
    this.tone(82, 0.055, 'sine', 0.018 * amount, 55);
  }
}

:root {
  --bg: #030609;
  --panel: rgba(6, 13, 18, 0.64);
  --line: rgba(139, 221, 238, 0.24);
  --line-bright: rgba(139, 235, 255, 0.7);
  --cyan: #72edff;
  --cyan-soft: #3a9cab;
  --orange: #ff7a2f;
  --orange-soft: #ff9d61;
  --white: #eaf6f7;
  --muted: #7d9aa1;
  --dim: #45626b;
  --sans: "Arial Narrow", "Roboto Condensed", "Helvetica Neue", Arial, sans-serif;
  --mono: ui-monospace, "Cascadia Code", "Roboto Mono", "SFMono-Regular", Menlo, monospace;
  --safe-top: env(safe-area-inset-top, 0px);
  --safe-bottom: env(safe-area-inset-bottom, 0px);
  --safe-left: env(safe-area-inset-left, 0px);
  --safe-right: env(safe-area-inset-right, 0px);
}

* {
  box-sizing: border-box;
}

html,
body {
  margin: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: var(--bg);
  color: var(--white);
  font-family: var(--sans);
  -webkit-user-select: none;
  user-select: none;
  overscroll-behavior: none;
  touch-action: none;
}

body {
  position: fixed;
  inset: 0;
}

button {
  font: inherit;
  color: inherit;
  border: 0;
  background: none;
  cursor: pointer;
}

canvas {
  position: fixed;
  inset: 0;
  display: block;
  width: 100%;
  height: 100%;
  outline: none;
  touch-action: none;
}

.hidden {
  display: none !important;
}

kbd {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 21px;
  height: 19px;
  padding: 0 5px;
  border: 1px solid rgba(152, 223, 238, 0.34);
  border-radius: 2px;
  color: #bcecf4;
  background: rgba(10, 24, 30, 0.72);
  font-family: var(--mono);
  font-size: 9px;
  line-height: 1;
  letter-spacing: 0.05em;
  box-shadow: inset 0 0 8px rgba(79, 214, 239, 0.06);
}

/* ---------- Screen effects ---------- */

#screenFx {
  position: fixed;
  inset: 0;
  z-index: 20;
  pointer-events: none;
  overflow: hidden;
}

.scanlines {
  position: absolute;
  inset: 0;
  opacity: 0.18;
  background: repeating-linear-gradient(
    to bottom,
    transparent 0,
    transparent 2px,
    rgba(121, 232, 255, 0.11) 3px,
    transparent 4px
  );
  mix-blend-mode: screen;
}

.vignette {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse at 50% 46%, transparent 45%, rgba(0, 4, 7, 0.2) 72%, rgba(0, 2, 4, 0.82) 115%),
    linear-gradient(180deg, rgba(0, 2, 4, 0.28), transparent 14%, transparent 82%, rgba(0, 2, 4, 0.5));
}

#flashFx {
  position: absolute;
  inset: 0;
  opacity: 0;
  background: radial-gradient(circle at 50% 50%, rgba(230, 255, 255, 0.95), rgba(76, 239, 255, 0.36) 23%, rgba(255, 115, 34, 0.12) 44%, transparent 70%);
  mix-blend-mode: screen;
}

#flashFx.teleport {
  animation: teleportFlash 0.68s ease-out forwards;
}

#flashFx.portal {
  animation: portalFlash 0.38s ease-out forwards;
  background: radial-gradient(circle at 50% 50%, rgba(255, 192, 120, 0.84), rgba(255, 91, 24, 0.3) 25%, transparent 61%);
}

#flashFx.hit {
  animation: hitFlash 0.5s ease-out forwards;
  background: radial-gradient(circle at 50% 50%, transparent 35%, rgba(255, 42, 18, 0.55) 100%);
}

#warnFx {
  position: absolute;
  inset: 0;
  opacity: 0;
  box-shadow: inset 0 0 110px 10px rgba(255, 44, 17, 0.62);
  transition: opacity 0.3s;
}

#warnFx.on {
  opacity: 1;
  animation: warningPulse 1.1s infinite;
}

@keyframes teleportFlash {
  0% { opacity: 0; transform: scale(0.55); }
  12% { opacity: 1; transform: scale(1); }
  100% { opacity: 0; transform: scale(1.4); }
}

@keyframes portalFlash {
  0% { opacity: 0; }
  20% { opacity: 0.9; }
  100% { opacity: 0; }
}

@keyframes hitFlash {
  0% { opacity: 0; }
  16% { opacity: 1; }
  100% { opacity: 0; }
}

@keyframes warningPulse {
  0%, 100% { opacity: 0.35; }
  50% { opacity: 0.85; }
}

/* ---------- HUD ---------- */

#hud {
  position: fixed;
  inset: 0;
  z-index: 30;
  pointer-events: none;
  font-family: var(--sans);
  text-transform: uppercase;
  animation: hudIn 0.8s ease-out both;
}

@keyframes hudIn {
  from { opacity: 0; }
  to { opacity: 1; }
}

.hud-top {
  position: absolute;
  top: calc(24px + var(--safe-top));
  left: calc(28px + var(--safe-left));
  right: calc(28px + var(--safe-right));
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
}

.chamber-block {
  position: relative;
  padding-left: 18px;
  min-width: 320px;
}

.chamber-block::before {
  content: "";
  position: absolute;
  left: 0;
  top: 2px;
  bottom: 2px;
  width: 2px;
  background: linear-gradient(180deg, var(--cyan), rgba(92, 223, 247, 0.08));
  box-shadow: 0 0 18px rgba(88, 226, 251, 0.5);
}

.microbrand {
  display: flex;
  align-items: center;
  gap: 7px;
  color: #99dce7;
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.18em;
  opacity: 0.8;
}

.microbrand b {
  color: var(--dim);
  font-weight: 400;
}

.glyph {
  width: 9px;
  height: 9px;
  border: 1px solid var(--cyan);
  transform: rotate(45deg);
  box-shadow: 0 0 9px rgba(100, 236, 255, 0.5);
}

.chamber-tag {
  margin-top: 9px;
  color: var(--orange);
  font-family: var(--mono);
  font-size: 10px;
  letter-spacing: 0.28em;
}

.chamber-name {
  margin-top: 2px;
  color: #effdff;
  font-size: clamp(28px, 3.1vw, 45px);
  font-weight: 700;
  line-height: 0.9;
  letter-spacing: 0.05em;
  text-shadow: 0 0 26px rgba(100, 226, 247, 0.22);
}

.objective-row {
  display: flex;
  gap: 12px;
  align-items: baseline;
  max-width: 540px;
  margin-top: 12px;
  padding-top: 9px;
  border-top: 1px solid var(--line);
  color: #b7d3d8;
}

.objective-label {
  flex: 0 0 auto;
  color: var(--cyan);
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.18em;
}

#objectiveText {
  font-family: var(--sans);
  font-size: 11px;
  letter-spacing: 0.12em;
  text-transform: none;
}

.status-stack {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 8px;
}

.status-card {
  width: 230px;
  padding: 13px 15px 12px;
  border: 1px solid var(--line);
  background:
    linear-gradient(135deg, rgba(73, 204, 232, 0.075), transparent 50%),
    rgba(3, 10, 14, 0.62);
  backdrop-filter: blur(12px);
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 11px), calc(100% - 11px) 100%, 0 100%);
  box-shadow: 0 12px 44px rgba(0, 0, 0, 0.2);
}

.status-head,
.link-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  color: #8fbbc3;
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.18em;
}

.status-dot {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: var(--cyan);
  box-shadow: 0 0 9px var(--cyan);
}

.core-row {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  margin-top: 4px;
}

#coreCount {
  color: #f1feff;
  font-size: 27px;
  font-weight: 700;
  line-height: 1;
  letter-spacing: 0.04em;
}

.core-bars {
  display: flex;
  gap: 4px;
}

.core-bars i {
  display: block;
  width: 17px;
  height: 5px;
  background: rgba(106, 234, 255, 0.13);
  box-shadow: inset 0 0 0 1px rgba(115, 236, 255, 0.24);
  transition: background 0.3s, box-shadow 0.3s;
}

.core-bars i.on {
  background: var(--cyan);
  box-shadow: 0 0 10px rgba(112, 239, 255, 0.8);
}

.status-rule {
  height: 1px;
  margin: 11px 0 9px;
  background: linear-gradient(90deg, transparent, var(--line), transparent);
}

.link-icon {
  display: block;
  width: 9px;
  height: 9px;
  border-radius: 50%;
  border: 1px solid var(--dim);
  box-shadow: 0 0 0 3px rgba(89, 213, 237, 0.05);
}

.link-row.linked {
  color: var(--orange-soft);
}

.link-row.linked .link-icon {
  border-color: var(--orange);
  background: var(--orange);
  box-shadow: 0 0 10px rgba(255, 122, 47, 0.9);
}

.timer-card {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 5px 10px;
  border-right: 1px solid var(--line);
  color: var(--dim);
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.18em;
}

.timer-card b {
  color: #a9dde5;
  font-size: 12px;
  font-weight: 400;
  letter-spacing: 0.08em;
}

/* Reticle */
.reticle {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 34px;
  height: 34px;
  transform: translate(-50%, -50%);
  opacity: 0.85;
  transition: opacity 0.15s;
}

.reticle i {
  position: absolute;
  display: block;
  width: 9px;
  height: 9px;
  border-color: rgba(213, 248, 254, 0.85);
  border-style: solid;
  transition: border-color 0.15s, transform 0.15s;
}

.r-tl { left: 0; top: 0; border-width: 1px 0 0 1px; }
.r-tr { right: 0; top: 0; border-width: 1px 1px 0 0; }
.r-bl { left: 0; bottom: 0; border-width: 0 0 1px 1px; }
.r-br { right: 0; bottom: 0; border-width: 0 1px 1px 0; }

.r-dot {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 3px;
  height: 3px;
  border-radius: 50%;
  background: #d9fbff;
  transform: translate(-50%, -50%);
  box-shadow: 0 0 8px rgba(160, 248, 255, 0.85);
}

.reticle.valid i {
  border-color: var(--orange);
  transform: scale(1.14);
}

.reticle.valid .r-dot {
  background: var(--orange);
  box-shadow: 0 0 12px rgba(255, 121, 43, 1);
}

.reticle.edge i {
  border-color: #ff4c38;
}

.reticle .aim-label {
  position: absolute;
  top: 45px;
  left: 50%;
  width: 220px;
  transform: translateX(-50%);
  color: rgba(178, 224, 232, 0.66);
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.18em;
  text-align: center;
  white-space: nowrap;
  opacity: 0;
  transition: opacity 0.15s, color 0.15s;
}

.reticle.valid .aim-label,
.reticle.edge .aim-label {
  opacity: 1;
}

.reticle.valid .aim-label { color: var(--orange-soft); }
.reticle.edge .aim-label { color: #ff5e4a; }

/* Objective marker */
.objective-marker {
  position: absolute;
  left: 50%;
  top: calc(50% + 76px);
  transform: translateX(-50%);
  display: flex;
  align-items: center;
  gap: 8px;
  color: var(--cyan);
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.24em;
  opacity: 0.85;
}

.objective-marker.unlocked {
  color: var(--orange-soft);
}

.marker-diamond {
  width: 10px;
  height: 10px;
  border: 1px solid currentColor;
  transform: rotate(45deg);
  box-shadow: 0 0 12px currentColor;
}

/* Bottom */
.hud-bottom {
  position: absolute;
  left: 0;
  right: 0;
  bottom: calc(22px + var(--safe-bottom));
  display: flex;
  justify-content: center;
  pointer-events: none;
}

.control-strip {
  display: flex;
  align-items: center;
  gap: 18px;
  padding: 8px 15px;
  color: rgba(133, 180, 189, 0.74);
  background: linear-gradient(90deg, transparent, rgba(3, 10, 14, 0.65) 16%, rgba(3, 10, 14, 0.65) 84%, transparent);
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.14em;
}

.control-strip span {
  display: flex;
  align-items: center;
  gap: 6px;
  white-space: nowrap;
}

.control-strip span.accent { color: var(--orange-soft); }

.mobile-strip { display: none; }

/* Toast */
.toast {
  position: absolute;
  left: 50%;
  bottom: 92px;
  transform: translateX(-50%) translateY(9px);
  max-width: min(520px, calc(100vw - 40px));
  padding: 9px 17px;
  border-left: 2px solid var(--orange);
  background: rgba(5, 14, 18, 0.76);
  color: #c7e7eb;
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: 0.14em;
  opacity: 0;
  transition: opacity 0.25s ease, transform 0.25s ease;
  backdrop-filter: blur(8px);
  text-align: center;
}

.toast.show {
  opacity: 1;
  transform: translateX(-50%) translateY(0);
}

.toast.cyan { border-left-color: var(--cyan); }

/* Level intro */
.level-intro {
  position: absolute;
  left: 50%;
  top: 47%;
  transform: translate(-50%, -50%);
  text-align: center;
  opacity: 0;
  pointer-events: none;
}

.level-intro.show {
  animation: introSequence 3.4s cubic-bezier(0.16, 0.8, 0.25, 1) both;
}

@keyframes introSequence {
  0% { opacity: 0; transform: translate(-50%, -48%) scale(0.96); filter: blur(5px); }
  13% { opacity: 1; transform: translate(-50%, -50%) scale(1); filter: blur(0); }
  74% { opacity: 1; }
  100% { opacity: 0; transform: translate(-50%, -52%) scale(1.015); }
}

.intro-kicker {
  color: var(--orange);
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: 0.5em;
  margin-left: 0.5em;
}

.intro-tag {
  margin-top: 12px;
  color: #a2d9e2;
  font-family: var(--mono);
  font-size: 11px;
  letter-spacing: 0.34em;
}

.intro-name {
  margin-top: 3px;
  color: #f2feff;
  font-size: clamp(42px, 7vw, 96px);
  font-weight: 700;
  line-height: 0.93;
  letter-spacing: 0.04em;
  text-shadow: 0 0 42px rgba(99, 229, 255, 0.2);
}

.intro-brief {
  margin-top: 12px;
  color: rgba(160, 207, 215, 0.82);
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: 0.13em;
}

/* ---------- Menu ---------- */

.menu-screen {
  position: fixed;
  inset: 0;
  z-index: 50;
  display: grid;
  grid-template-columns: minmax(440px, 0.7fr) 1fr;
  grid-template-rows: auto 1fr auto;
  padding: calc(28px + var(--safe-top)) calc(38px + var(--safe-right)) calc(22px + var(--safe-bottom)) calc(38px + var(--safe-left));
  background: #020508;
  overflow: hidden;
}

.menu-shade {
  position: absolute;
  inset: 0;
  z-index: -1;
  background:
    linear-gradient(90deg, rgba(2, 6, 9, 0.96) 0%, rgba(2, 7, 10, 0.8) 36%, rgba(2, 7, 10, 0.16) 64%, rgba(2, 6, 9, 0.38) 100%),
    linear-gradient(180deg, rgba(3, 9, 13, 0.46), transparent 24%, transparent 72%, rgba(1, 4, 6, 0.9));
}

.menu-screen::after {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background:
    linear-gradient(90deg, transparent 0 49.93%, rgba(109, 233, 255, 0.12) 50%, transparent 50.07%),
    linear-gradient(0deg, transparent 0 49.93%, rgba(109, 233, 255, 0.05) 50%, transparent 50.07%);
  mix-blend-mode: screen;
  opacity: 0.3;
}

.menu-header {
  grid-column: 1 / -1;
  display: flex;
  align-items: center;
  gap: 11px;
  color: #9bdde5;
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.19em;
  line-height: 1.45;
}

.logo-mark {
  position: relative;
  width: 31px;
  height: 31px;
  border: 1px solid rgba(110, 233, 255, 0.56);
  transform: rotate(45deg);
  margin-right: 6px;
}

.logo-mark span {
  position: absolute;
  border: 1px solid var(--cyan);
}

.logo-mark span:nth-child(1) { inset: 6px; }
.logo-mark span:nth-child(2) { inset: 11px; border-color: var(--orange); }
.logo-mark span:nth-child(3) { left: 14px; top: 14px; width: 3px; height: 3px; background: #fff; border: 0; box-shadow: 0 0 8px #fff; }

.logo-copy b,
.menu-header-right b {
  color: #e7fbff;
  font-weight: 500;
  letter-spacing: 0.14em;
}

.menu-header-right {
  margin-left: auto;
  text-align: right;
  color: #537c85;
}

.menu-content {
  align-self: center;
  max-width: 620px;
  padding-left: 2px;
  padding-bottom: 4vh;
  position: relative;
  z-index: 2;
}

.menu-kicker {
  display: flex;
  align-items: center;
  gap: 11px;
  color: var(--cyan);
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: 0.26em;
  opacity: 0.86;
  animation: riseIn 0.85s 0.08s both;
}

.menu-kicker span {
  width: 27px;
  height: 1px;
  background: var(--orange);
  box-shadow: 0 0 9px rgba(255, 120, 44, 0.7);
}

.menu-content h1 {
  margin: 13px 0 0;
  color: #ecfbff;
  font-size: clamp(74px, 11vw, 166px);
  font-weight: 700;
  line-height: 0.69;
  letter-spacing: -0.045em;
  text-transform: uppercase;
  animation: riseIn 0.95s 0.14s both;
}

.h1-thin,
.h1-bold {
  display: block;
}

.h1-thin {
  color: transparent;
  -webkit-text-stroke: 1px rgba(198, 247, 255, 0.78);
  text-stroke: 1px rgba(198, 247, 255, 0.78);
  font-weight: 400;
  letter-spacing: 0.01em;
  padding-left: 6px;
  transform: scaleY(1.06);
  transform-origin: left bottom;
}

.h1-bold {
  color: var(--white);
  text-shadow: 0 0 46px rgba(82, 222, 248, 0.16);
  padding-left: 0;
}

.h1-bold::after {
  content: "PORTAL";
  position: absolute;
  color: var(--orange);
  opacity: 0;
  pointer-events: none;
}

.menu-rule {
  display: flex;
  align-items: center;
  gap: 14px;
  width: min(390px, 74%);
  margin: 20px 0 18px;
  color: var(--orange);
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: 0.16em;
  animation: riseIn 1s 0.23s both;
}

.menu-rule span {
  flex: 1;
  height: 1px;
  background: linear-gradient(90deg, var(--orange), rgba(255, 122, 47, 0.04));
}

.menu-rule b { font-weight: 400; }

.menu-lede {
  margin: 0;
  color: #d8f5f8;
  font-size: clamp(18px, 1.8vw, 25px);
  font-weight: 400;
  line-height: 1.2;
  letter-spacing: 0.015em;
  text-transform: none;
  animation: riseIn 1s 0.28s both;
}

.menu-body {
  max-width: 440px;
  margin: 12px 0 0;
  color: #7fabb3;
  font-size: 13px;
  line-height: 1.6;
  text-transform: none;
  animation: riseIn 1s 0.34s both;
}

.start-btn {
  position: relative;
  display: flex;
  align-items: center;
  gap: 13px;
  width: 288px;
  margin-top: 25px;
  padding: 14px 16px;
  border: 1px solid rgba(255, 124, 47, 0.65);
  background: linear-gradient(90deg, rgba(255, 106, 28, 0.17), rgba(255, 106, 28, 0.03));
  color: #ffd8c3;
  text-align: left;
  letter-spacing: 0.14em;
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 9px), calc(100% - 9px) 100%, 0 100%);
  animation: riseIn 1s 0.4s both;
  transition: background 0.2s, border-color 0.2s, color 0.2s;
}

.start-btn::before {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(100deg, transparent 30%, rgba(255, 139, 76, 0.22), transparent 70%);
  transform: translateX(-120%);
  transition: transform 0.55s ease;
}

.start-btn:hover {
  border-color: var(--orange-soft);
  background: linear-gradient(90deg, rgba(255, 106, 28, 0.3), rgba(255, 106, 28, 0.06));
  color: #fff;
}

.start-btn:hover::before {
  transform: translateX(120%);
}

.btn-index {
  color: var(--orange);
  font-family: var(--mono);
  font-size: 9px;
  opacity: 0.8;
}

.btn-label {
  font-family: var(--mono);
  font-size: 11px;
  font-weight: 600;
}

.btn-arrow {
  margin-left: auto;
  font-family: var(--mono);
  font-size: 17px;
  font-weight: 400;
}

.menu-meta {
  display: flex;
  gap: 22px;
  margin-top: 22px;
  color: #466770;
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.16em;
  animation: riseIn 1s 0.5s both;
}

.menu-meta span {
  position: relative;
  padding-left: 10px;
}

.menu-meta span::before {
  content: "";
  position: absolute;
  left: 0;
  top: 50%;
  width: 4px;
  height: 4px;
  border: 1px solid var(--dim);
  transform: translateY(-50%) rotate(45deg);
}

.menu-aside {
  align-self: center;
  justify-self: end;
  width: 280px;
  padding: 10px 0 0;
  position: relative;
  z-index: 2;
  animation: riseIn 1s 0.42s both;
}

.aside-line {
  width: 100%;
  height: 1px;
  background: linear-gradient(90deg, transparent, var(--line-bright), transparent);
  margin-bottom: 22px;
}

.aside-block {
  padding: 0 0 18px;
  margin-bottom: 16px;
  border-bottom: 1px solid rgba(109, 208, 228, 0.13);
}

.aside-label {
  display: block;
  margin-bottom: 11px;
  color: var(--cyan);
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.24em;
}

.aside-block div {
  display: flex;
  align-items: center;
  gap: 11px;
  margin-top: 6px;
  color: #7e9da4;
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.08em;
}

.aside-block p {
  margin: 0;
  color: #75969e;
  font-size: 11px;
  line-height: 1.55;
  text-transform: none;
}

.aside-foot {
  color: #3f5b63;
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.15em;
  line-height: 1.6;
}

.menu-footer {
  grid-column: 1 / -1;
  display: flex;
  justify-content: space-between;
  align-items: center;
  color: #3f5a62;
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.18em;
}

.menu-load {
  display: flex;
  align-items: center;
  gap: 7px;
  color: #668f98;
}

.menu-load i {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: #5dffac;
  box-shadow: 0 0 8px #5dffac;
}

@keyframes riseIn {
  from { opacity: 0; transform: translateY(15px); }
  to { opacity: 1; transform: translateY(0); }
}

/* ---------- Modals ---------- */

.modal-screen {
  position: fixed;
  inset: 0;
  z-index: 60;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
  background: rgba(1, 5, 8, 0.66);
  backdrop-filter: blur(9px);
  animation: modalIn 0.35s ease-out both;
}

@keyframes modalIn {
  from { opacity: 0; }
  to { opacity: 1; }
}

.modal-card {
  position: relative;
  width: min(590px, 100%);
  padding: 35px 38px 27px;
  border: 1px solid rgba(110, 223, 242, 0.26);
  background:
    linear-gradient(140deg, rgba(78, 218, 246, 0.075), transparent 40%),
    rgba(3, 10, 14, 0.92);
  box-shadow: 0 35px 100px rgba(0, 0, 0, 0.6), inset 0 0 60px rgba(76, 213, 240, 0.025);
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 18px), calc(100% - 18px) 100%, 0 100%);
}

.modal-card::before {
  content: "";
  position: absolute;
  left: 0;
  top: 0;
  width: 78px;
  height: 2px;
  background: var(--orange);
  box-shadow: 0 0 15px rgba(255, 122, 47, 0.55);
}

.modal-kicker {
  color: var(--orange);
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: 0.27em;
}

.modal-card h2 {
  margin: 7px 0 0;
  color: #eefeff;
  font-size: clamp(34px, 5vw, 62px);
  font-weight: 700;
  line-height: 0.92;
  letter-spacing: 0.025em;
  text-transform: uppercase;
}

.modal-card > p {
  max-width: 410px;
  margin: 12px 0 0;
  color: #789ba3;
  font-size: 12px;
  line-height: 1.5;
  text-transform: none;
}

.modal-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 9px;
  margin-top: 25px;
}

.modal-actions button {
  min-height: 42px;
  padding: 0 17px;
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.14em;
  transition: background 0.2s, border-color 0.2s, color 0.2s;
}

.modal-actions .primary {
  display: flex;
  align-items: center;
  gap: 22px;
  border: 1px solid rgba(255, 124, 50, 0.64);
  background: rgba(255, 105, 28, 0.15);
  color: #ffd6c1;
}

.modal-actions .primary:hover {
  background: rgba(255, 105, 28, 0.29);
  border-color: var(--orange-soft);
  color: #fff;
}

.modal-actions .primary span {
  font-size: 14px;
}

.modal-actions .secondary {
  border: 1px solid rgba(105, 218, 238, 0.26);
  background: rgba(65, 178, 199, 0.06);
  color: #a5d6de;
}

.modal-actions .secondary:hover {
  border-color: var(--cyan);
  background: rgba(65, 178, 199, 0.14);
  color: #fff;
}

.modal-actions .ghost {
  border: 1px solid transparent;
  color: #54727a;
}

.modal-actions .ghost:hover {
  color: #a8ced4;
}

.modal-foot {
  margin-top: 23px;
  padding-top: 12px;
  border-top: 1px solid rgba(105, 206, 225, 0.13);
  color: #3f5d65;
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.18em;
}

.complete-card::before {
  background: var(--cyan);
  box-shadow: 0 0 15px rgba(78, 227, 255, 0.65);
}

.result-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 10px;
  margin-top: 23px;
}

.result-grid div {
  padding: 11px 12px;
  border-left: 1px solid rgba(97, 214, 235, 0.22);
  background: rgba(87, 211, 237, 0.035);
}

.result-grid span {
  display: block;
  color: #5f858d;
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.16em;
}

.result-grid b {
  display: block;
  margin-top: 5px;
  color: #dffbff;
  font-family: var(--mono);
  font-size: 19px;
  font-weight: 400;
}

/* Ending */
.ending-card {
  width: min(800px, 100%);
  padding: 42px 46px 30px;
  border-top: 1px solid rgba(255, 132, 58, 0.45);
  border-bottom: 1px solid rgba(85, 223, 249, 0.22);
  background:
    radial-gradient(circle at 50% 0, rgba(255, 120, 43, 0.12), transparent 52%),
    rgba(2, 8, 11, 0.92);
  box-shadow: 0 40px 120px rgba(0, 0, 0, 0.6);
  text-align: center;
}

.ending-kicker {
  color: var(--orange);
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: 0.3em;
}

.ending-card h2 {
  margin: 15px 0 0;
  color: #f4feff;
  font-size: clamp(43px, 8vw, 96px);
  font-weight: 700;
  line-height: 0.76;
  letter-spacing: 0.015em;
}

.ending-card h2 span {
  color: transparent;
  -webkit-text-stroke: 1px var(--cyan);
  text-stroke: 1px var(--cyan);
}

.ending-card > p {
  margin: 18px auto 0;
  color: #7c9da5;
  font-size: 13px;
  text-transform: none;
}

.ending-stats {
  display: flex;
  justify-content: center;
  gap: 42px;
  margin: 30px 0 25px;
}

.ending-stats div {
  min-width: 110px;
}

.ending-stats b {
  display: block;
  color: #e1fcff;
  font-family: var(--mono);
  font-size: 27px;
  font-weight: 400;
}

.ending-stats span {
  display: block;
  margin-top: 4px;
  color: #5e7f87;
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.18em;
}

.ending-card .primary {
  min-height: 46px;
  padding: 0 23px;
  border: 1px solid rgba(255, 124, 50, 0.62);
  background: rgba(255, 105, 28, 0.14);
  color: #ffd7c4;
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: 0.16em;
}

.ending-card .primary:hover {
  background: rgba(255, 105, 28, 0.3);
  color: #fff;
}

.ending-card .primary span {
  margin-left: 20px;
}

.ending-foot {
  margin-top: 28px;
  color: #3c5860;
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.18em;
}

/* ---------- Touch ---------- */

.touch-controls {
  position: fixed;
  inset: 0;
  z-index: 40;
  pointer-events: none;
}

.joystick {
  position: absolute;
  left: calc(25px + var(--safe-left));
  bottom: calc(28px + var(--safe-bottom));
  width: 122px;
  height: 122px;
  border: 1px solid rgba(131, 229, 247, 0.28);
  border-radius: 50%;
  background: rgba(4, 14, 19, 0.26);
  pointer-events: auto;
  touch-action: none;
}

.joy-ring {
  position: absolute;
  inset: 17px;
  border: 1px solid rgba(111, 222, 243, 0.18);
  border-radius: 50%;
}

.stick {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 46px;
  height: 46px;
  border: 1px solid rgba(137, 238, 255, 0.64);
  border-radius: 50%;
  background: radial-gradient(circle, rgba(107, 231, 255, 0.35), rgba(10, 34, 43, 0.48));
  box-shadow: 0 0 20px rgba(78, 219, 244, 0.2);
  transform: translate(-50%, -50%);
}

.touch-action-stack {
  position: absolute;
  right: calc(22px + var(--safe-right));
  bottom: calc(28px + var(--safe-bottom));
  display: flex;
  align-items: flex-end;
  gap: 9px;
  pointer-events: auto;
}

.touch-btn {
  width: 68px;
  height: 68px;
  border: 1px solid rgba(139, 236, 255, 0.4);
  border-radius: 50%;
  background: rgba(6, 24, 31, 0.38);
  color: #b9f4ff;
  font-family: var(--mono);
  font-size: 25px;
  backdrop-filter: blur(6px);
  touch-action: none;
}

.touch-btn:active {
  background: rgba(90, 220, 245, 0.24);
}

.touch-btn.portal {
  width: 82px;
  height: 82px;
  border-color: rgba(255, 128, 54, 0.6);
  background: rgba(84, 27, 5, 0.42);
  color: #ffcfb4;
  box-shadow: 0 0 25px rgba(255, 100, 24, 0.12);
}

.touch-btn.small {
  width: 44px;
  height: 44px;
  font-size: 17px;
  opacity: 0.8;
}

.audio-badge {
  position: fixed;
  right: 22px;
  bottom: 74px;
  z-index: 45;
  color: #7acbd8;
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.2em;
  opacity: 0;
  transition: opacity 0.3s;
  pointer-events: none;
}

.audio-badge.show { opacity: 0.8; }

/* ---------- Responsive ---------- */

@media (max-width: 980px) {
  .menu-screen {
    grid-template-columns: 1fr;
    padding: calc(22px + var(--safe-top)) calc(24px + var(--safe-right)) calc(18px + var(--safe-bottom)) calc(24px + var(--safe-left));
  }

  .menu-aside {
    display: none;
  }

  .menu-content {
    align-self: center;
    max-width: 600px;
    padding-bottom: 0;
  }

  .menu-shade {
    background:
      linear-gradient(180deg, rgba(2, 7, 10, 0.8), rgba(2, 7, 10, 0.56) 50%, rgba(2, 7, 10, 0.9)),
      linear-gradient(90deg, rgba(2, 6, 9, 0.8), transparent 70%);
  }

  .menu-content h1 {
    font-size: clamp(70px, 16vw, 145px);
  }
}

@media (max-width: 700px) {
  .hud-top {
    top: calc(14px + var(--safe-top));
    left: calc(16px + var(--safe-left));
    right: calc(16px + var(--safe-right));
  }

  .chamber-block {
    min-width: 0;
    padding-left: 12px;
  }

  .microbrand,
  .objective-row {
    display: none;
  }

  .chamber-tag {
    font-size: 8px;
    letter-spacing: 0.2em;
  }

  .chamber-name {
    max-width: 45vw;
    font-size: 24px;
  }

  .status-card {
    width: 146px;
    padding: 9px 10px;
  }

  #coreCount { font-size: 20px; }
  .core-bars { display: none; }
  .timer-card { padding-right: 0; border-right: 0; }
  .timer-card span { display: none; }

  .control-strip:not(.mobile-strip) { display: none; }
  .mobile-strip { display: flex; gap: 13px; font-size: 6px; }
  .toast { bottom: 180px; }
  .level-intro { top: 40%; }

  .menu-content h1 {
    font-size: clamp(64px, 18vw, 116px);
  }

  .menu-content {
    padding-bottom: 4vh;
  }

  .menu-lede { font-size: 18px; }
  .menu-body { max-width: 90%; font-size: 12px; }
  .menu-meta { gap: 11px; font-size: 6px; flex-wrap: wrap; }
  .menu-header-right { display: none; }
  .menu-footer span:first-child { display: none; }
  .menu-footer { justify-content: flex-end; }

  .result-grid { grid-template-columns: 1fr; }
  .modal-card { padding: 27px 23px 22px; }
  .ending-card { padding: 32px 22px 24px; }
  .ending-stats { gap: 14px; }
  .ending-stats div { min-width: 0; flex: 1; }
  .ending-stats b { font-size: 20px; }
  .modal-actions { flex-direction: column; }
  .modal-actions button { width: 100%; justify-content: center; }
}

@media (max-width: 420px) {
  .status-card { width: 132px; }
  .menu-content h1 { font-size: 61px; }
  .menu-kicker { font-size: 7px; letter-spacing: 0.16em; }
  .menu-meta { display: none; }
  .touch-btn { width: 60px; height: 60px; }
  .touch-btn.portal { width: 72px; height: 72px; }
  .joystick { width: 105px; height: 105px; }
}

@media (pointer: coarse) {
  .mobile-strip { display: flex; }
  .control-strip:not(.mobile-strip) { display: none; }
}

import * as THREE from 'three';
