import { createAssets, makeGlowTexture } from './assets.js';
import { buildLevel, setPanelEnabled, PORTAL_W, PORTAL_H } from './levels.js';
import { AudioManager } from './audio.js';

const $ = (id) => document.getElementById(id);

const ui = {
  canvas: $('scene'),
  hud: $('hud'),
  menu: $('menu'),
  startBtn: $('startBtn'),
